<script setup>
import {ref,reactive,onMounted,onBeforeUnmount} from 'vue'
import L from 'leaflet'
import MapIcon from './components/MapIcon.vue'
const mapEl=ref(null),panel=ref(false),query=ref(''),focused=ref('place'),suggestions=ref([]),place=ref(null),picking=ref(''),mode=ref('bike'),ai=ref(false),preference=ref('综合考虑时间和步行距离'),error=ref(''),parkingError=ref(''),busy=ref(false),result=ref(null),recommendations=ref([])
const endpoints=reactive({origin:{text:'',point:null},destination:{text:'',point:null}})
const showParking=ref(true),showBus=ref(false),parkingItems=ref([]),bus=ref({routes:[],stops:[],vehicles:[]})
let map,roads,markers,routeLayer,parkingLayer,percentLayer,busLayer,observer,timer,searchTimer,searchId=0,runId=0,stopped=false
async function api(path,body){const r=await fetch('/api'+path,{...(body?{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify(body)}:{}),signal:AbortSignal.timeout(45000)});const d=await r.json();if(!r.ok)throw Error(typeof d.detail==='string'?d.detail:'请求失败');return d}
function invalidate(){runId++;result.value=null;recommendations.value=[];routeLayer?.clearLayers();error.value='';parkingError.value='';if(parkingLayer)drawParking()}
function drawMarkers(){markers?.clearLayers();for(const [key,e] of Object.entries(endpoints)){if(!e.point)continue;const name=document.createElement('span');name.textContent=e.text;L.circleMarker([e.point.latitude,e.point.longitude],{radius:8,color:'white',weight:3,fillColor:key==='origin'?'#1a73e8':'#e94235',fillOpacity:1}).bindTooltip(name).addTo(markers)}}
function search(key){if(key!=='place'){endpoints[key].point=null;invalidate();drawMarkers()}focused.value=key;const value=key==='place'?query.value:endpoints[key].text;const token=++searchId;suggestions.value=[];clearTimeout(searchTimer);if(!value.trim())return;searchTimer=setTimeout(async()=>{try{const d=await api('/navigation/places?q='+encodeURIComponent(value));if(token===searchId&&!stopped)suggestions.value=d.items}catch(e){if(token===searchId)error.value=e.message}},220)}
function choose(key,item){searchId++;suggestions.value=[];focused.value='';picking.value='';invalidate();const e={text:item.name,point:{latitude:item.latitude,longitude:item.longitude}};if(key==='place'){place.value=item;query.value=item.name;endpoints.destination=e}else endpoints[key]=e;drawMarkers();map.panTo([item.latitude,item.longitude]);if(endpoints.destination.point)nearby()}
function directions(){panel.value=true;focused.value='';suggestions.value=[]}
function swap(){[endpoints.origin,endpoints.destination]=[endpoints.destination,endpoints.origin];invalidate();drawMarkers()}
function renderRoute(d){result.value=d;routeLayer.clearLayers();L.geoJSON(d.geojson,{style:f=>({color:f?.properties?.segment==='walk'?'#159da9':'#1a73e8',weight:6,dashArray:f?.properties?.segment==='walk'?'7 8':undefined})}).addTo(routeLayer);const b=routeLayer.getBounds();if(b.isValid())map.fitBounds(b,{paddingTopLeft:[innerWidth>720?440:30,90],paddingBottomRight:[40,innerWidth>720?70:300],maxZoom:18})}
function body(){return {origin:endpoints.origin.point,destination:endpoints.destination.point,mode:mode.value}}
async function nearby(){if(!endpoints.destination.point)return;const token=runId;parkingError.value='';try{const d=await api('/navigation/parking-recommendations',{...body(),origin:endpoints.origin.point||endpoints.destination.point});if(token===runId&&!stopped){recommendations.value=d.items;drawParking();if(!d.items.length)parkingError.value='终点800米内暂无路网可达的停车区'}}catch(e){if(token===runId)parkingError.value=e.message}}
async function navigate(){if(!endpoints.origin.point||!endpoints.destination.point){error.value='请选择起点和终点';return}invalidate();busy.value=true;const token=runId;try{const [d]=await Promise.all([api(ai.value?'/navigation/recommend':'/navigation/route',{...body(),...(ai.value?{preference:preference.value}:{})}),nearby()]);if(token===runId&&!stopped)renderRoute(d)}catch(e){if(token===runId)error.value=e.message}finally{busy.value=false}}
function chooseParking(p){if(!endpoints.origin.point){directions();error.value='选择起点后可显示经此停车区的完整路线';return}renderRoute({...p,mode:mode.value,notice:'蓝线：到停车区；青色虚线：停车后步行。入口接驳与停车操作未计时。'})}
const sourceText=s=>s==='simulated'?'模拟数据':'Qwen上传估算 · 非实时'
const color=p=>p.percent>=100?'#d93025':p.percent>=80?'#ed9300':'#188038'
function toggleLayers(){for(const [layer,visible] of [[parkingLayer,showParking.value],[percentLayer,showParking.value],[busLayer,showBus.value]]){if(!layer)continue;if(visible&&!map.hasLayer(layer))layer.addTo(map);if(!visible&&map.hasLayer(layer))map.removeLayer(layer)}}
function drawParking(){parkingLayer.clearLayers();percentLayer.clearLayers();for(const p of parkingItems.value){const layer=L.geoJSON(p.geometry,{style:{color:color(p),weight:2,fillOpacity:.18}});function popup(){const c=document.createElement('div'),b=document.createElement('b'),detail=document.createElement('p'),button=document.createElement('button');b.textContent=p.name;detail.textContent=`容载率 ${p.percent}% · 总数 ${p.count} / 容量 ${p.capacity} · 违停 ${p.illegal_count??'未分类'} · ${sourceText(p.source)} · ${new Date(p.updated_at).toLocaleString()}`;button.textContent='设为终点';button.onclick=()=>{const center=layer.getBounds().getCenter();directions();choose('destination',{name:p.name,latitude:center.lat,longitude:center.lng});map.closePopup()};c.append(b,detail,button);return c}if(recommendations.value[0]?.area_id===p.id){const label=document.createElement('span');label.textContent='推荐 · '+p.name;layer.setStyle({weight:4});layer.bindTooltip(label,{permanent:true,direction:'top'})}layer.bindPopup(popup).addTo(parkingLayer);const badge=document.createElement('span');badge.textContent=`P ${p.percent}%`;badge.style.cssText=`background:white;color:${color(p)};padding:6px 9px;border:1px solid currentColor;border-radius:16px;white-space:nowrap;font-weight:700;box-shadow:0 2px 7px #0002`;L.marker(layer.getBounds().getCenter(),{icon:L.divIcon({html:badge,className:'parking-percentage',iconSize:[90,30]}),title:p.name}).bindPopup(popup).addTo(percentLayer)}toggleLayers()}
function drawBus(){busLayer.clearLayers();for(const r of bus.value.routes){const label=document.createElement('span');label.textContent=r.name+' · '+(bus.value.vehicles.filter(v=>v.route_id===r.id).map(v=>`${v.name}：${v.observation?v.observation.count+'人 / '+v.observation.percent+'% · '+(v.observation.source==='camera'?'摄像头':'手动测试')+' · '+new Date(v.observation.captured_at).toLocaleTimeString():'暂无人数'}`).join('；')||'暂无车辆');L.polyline(r.points.map(p=>[p.latitude,p.longitude]),{color:r.color,weight:5}).bindTooltip(label).addTo(busLayer)}for(const s of bus.value.stops){const label=document.createElement('span');label.textContent=s.name;L.circleMarker([s.latitude,s.longitude],{radius:6,color:'#8b5cf6',fillColor:'white',fillOpacity:1}).bindTooltip(label,{permanent:true}).addTo(busLayer)}toggleLayers()}
async function refreshData(){const r=await Promise.allSettled([api('/parking/overview'),api('/transit')]);if(stopped)return;if(r[0].status==='fulfilled'){parkingItems.value=r[0].value.items;drawParking()}else parkingError.value='停车数据暂时无法更新';if(r[1].status==='fulfilled'){bus.value=r[1].value;drawBus()}if(endpoints.destination.point)nearby()}
function fitCampus(){if(roads?.getBounds().isValid())map.fitBounds(roads.getBounds(),{paddingTopLeft:[innerWidth>720?420:30,90],paddingBottomRight:[30,70]})}
onMounted(async()=>{map=L.map(mapEl.value,{zoomControl:false,center:[0,0],zoom:16});L.control.zoom({position:'bottomright'}).addTo(map);L.tileLayer('https://tile.openstreetmap.org/{z}/{x}/{y}.png',{maxZoom:19,attribution:'© <a href="https://www.openstreetmap.org/copyright">OpenStreetMap contributors</a>'}).addTo(map);markers=L.layerGroup().addTo(map);routeLayer=L.featureGroup().addTo(map);parkingLayer=L.featureGroup();percentLayer=L.layerGroup();busLayer=L.layerGroup();map.on('click',e=>{if(picking.value&&!busy.value)choose(picking.value,{name:`地图选点 ${e.latlng.lat.toFixed(5)}, ${e.latlng.lng.toFixed(5)}`,latitude:e.latlng.lat,longitude:e.latlng.lng})});observer=new ResizeObserver(()=>map.invalidateSize());observer.observe(mapEl.value);try{const d=await api('/navigation/map');if(stopped)return;const named=new Set();roads=L.geoJSON(d,{style:f=>({color:f.properties.highway==='cycleway'?'#22a447':['footway','pedestrian','steps'].includes(f.properties.highway)?'#66CCFF':'#f6c344',weight:4}),onEachFeature(f,l){if(f.properties.name){const text=document.createElement('span');text.textContent=f.properties.name;l.bindTooltip(text,{permanent:!named.has(f.properties.name),direction:'center',className:'campus-road-name'});named.add(f.properties.name)}}}).addTo(map);fitCampus();await refreshData();if(!stopped)timer=setInterval(refreshData,15000)}catch(e){if(!stopped)error.value=e.message}})
onBeforeUnmount(()=>{stopped=true;clearInterval(timer);clearTimeout(searchTimer);searchId++;runId++;observer?.disconnect();map?.remove()})
</script>
<template>
 <main class="navigation-app">
  <div ref="mapEl" class="navigation-map" aria-label="校园导航地图"></div>
  <div class="brand"><b>CampusFlow</b><span>长安大学 · 渭水校区</span><a href="/debug" target="_blank" rel="noopener">内部调试 ↗</a></div>
  <div class="search-shell" v-if="!panel"><MapIcon name="search" :size="22"/><input v-model="query" aria-label="搜索校园地点" placeholder="搜索宿舍、教学楼、停车区" @input="search('place')" @focus="focused='place'"><button aria-label="打开导航" title="路线" @click="directions"><MapIcon name="route"/></button><button aria-label="AI推荐" @click="directions();ai=true">AI</button></div>
  <ul v-if="!panel&&focused==='place'&&suggestions.length" class="place-suggestions"><li v-for="s in suggestions" :key="s.id"><button @click="choose('place',s)">{{s.name}}</button></li></ul>
  <aside v-if="panel||place" class="navigation-panel" :class="{compact:!panel}" aria-label="地点与导航">
   <template v-if="panel"><div class="panel-head"><h1>{{ai?'AI 出行推荐':'路线规划'}}</h1><button aria-label="关闭导航" @click="panel=false;ai=false;picking=''">×</button></div>
    <div v-for="key in ['origin','destination']" :key="key" class="endpoint"><label :for="key">{{key==='origin'?'起点':'终点'}}</label><div class="entry"><input :id="key" v-model="endpoints[key].text" :disabled="busy" :placeholder="key==='origin'?'选择起点':'选择目的地'" @input="search(key)" @focus="focused=key"><button :disabled="busy" :class="{active:picking===key}" @click="picking=key;focused='';suggestions=[]">地图选点</button></div><ul v-if="focused===key&&suggestions.length" class="suggestions"><li v-for="s in suggestions" :key="s.id"><button @click="choose(key,s)">{{s.name}}</button></li></ul></div>
    <div class="mode-row"><button :disabled="busy" @click="swap">⇅ 交换</button><button :disabled="busy" :class="{active:mode==='walk'}" @click="mode='walk';invalidate()">步行</button><button :disabled="busy" :class="{active:mode==='bike'}" @click="mode='bike';invalidate()">骑行</button><button :class="{active:ai}" @click="ai=!ai">AI 推荐</button></div>
    <p v-if="picking" class="tip">点击地图设置{{picking==='origin'?'起点':'终点'}}</p><textarea v-if="ai" v-model="preference" maxlength="500" placeholder="说说你的出行偏好"></textarea><button class="primary" :disabled="busy" @click="navigate">{{busy?'正在规划…':ai?'让 AI 推荐':'查找路线'}}</button>
    <section v-if="result" class="route-result"><strong>{{result.duration_minutes}} 分钟</strong><span>{{result.area_id?'经 '+result.name:result.mode==='walk'?'步行':'骑行'}} · {{result.distance_m}} 米</span><p v-if="result.ai">{{result.ai.reason}}</p><p>{{result.notice}}</p></section>
   </template>
   <template v-else><div class="panel-head"><h1>{{place.name}}</h1><button aria-label="关闭地点" @click="place=null">×</button></div><p class="muted">校园地点 · {{place.location_type==='building_center'?'建筑中心':'地图位置'}}</p><button class="primary" @click="directions">到这里去</button></template>
   <section v-if="endpoints.destination.point" class="parking-results"><h2>终点附近停车区</h2><p class="muted">结合到达时间、停车后步行和容载率排序 · 800米范围</p><button v-for="(p,i) in recommendations" :key="p.area_id" class="parking-card" @click="chooseParking(p)"><b>{{i===0?'推荐 · ':''}}{{p.name}}</b><span>停车后步行 {{p.walk_minutes}} 分钟 <em :style="{color:color(p)}">{{p.percent}}%</em></span><small>{{sourceText(p.source)}} · 违停 {{p.illegal_count??'未分类'}} 辆 · 容量 {{p.capacity}}</small></button><p v-if="parkingError" class="muted">{{parkingError}}</p></section>
   <p v-if="error" class="error" role="alert">{{error}}</p><p v-if="panel" class="muted">时间按步行4.5km/h、骑行12km/h估算。AI推荐会调用百炼。</p>
  </aside>
  <div v-if="error&&!panel&&!place" class="error floating-error" role="alert">{{error}}</div>
  <div class="layer-switches" aria-label="地图显示开关"><label><input v-model="showParking" type="checkbox" @change="toggleLayers">停车区域与容载率</label><label><input v-model="showBus" type="checkbox" @change="toggleLayers">公交线路</label></div>
  <button class="campus-fit" @click="fitCampus">查看全校</button><div class="road-legend"><span><i style="background:#f6c344"></i>道路／路径</span><span><i style="background:#22a447"></i>自行车道</span><span><i style="background:#66CCFF"></i>步行道</span></div>
 </main>
</template>
<style scoped>
.navigation-app{height:100dvh;min-height:550px;position:relative;color:#202124;font:14px/1.5 system-ui}.navigation-map{position:absolute;inset:0;background:#e9eee8}.brand{position:absolute;right:20px;top:20px;z-index:700;background:white;padding:10px 16px;border-radius:24px;display:flex;gap:12px;box-shadow:0 2px 10px #0002}.brand b{color:#1a73e8}.brand span,.brand a{font-size:11px;color:#64748b}.search-shell{position:absolute;top:20px;left:20px;width:390px;z-index:900;background:white;padding:8px 12px;border-radius:30px;box-shadow:0 3px 16px #0003;display:flex;align-items:center;gap:10px}.search-shell input{flex:1;min-width:0;border:0;padding:8px 0;outline:none}.search-shell button{color:#1a73e8;border:0!important;border-left:1px solid #ddd!important;border-radius:0!important;display:flex;align-items:center;font-weight:700}.navigation-app button{cursor:pointer;border:1px solid #dadce0;background:white;color:inherit;border-radius:20px;padding:9px 12px}.navigation-app button:disabled{opacity:.5;cursor:default}.navigation-panel{position:absolute;top:20px;left:20px;bottom:70px;width:390px;z-index:800;background:white;border-radius:18px;box-shadow:0 3px 16px #0003;padding:22px;overflow:auto}.navigation-panel.compact{top:88px;bottom:auto;max-height:calc(100dvh - 160px)}.panel-head{display:flex;align-items:center;justify-content:space-between}.panel-head h1{font-size:21px;margin:0}.endpoint{margin-top:18px}.endpoint label{font-size:12px;font-weight:600}.entry{display:flex;gap:6px;margin-top:5px}.entry input{width:100%;min-width:0;border:1px solid #dadce0;border-radius:8px;padding:11px}.entry button{white-space:nowrap;border-radius:8px;font-size:11px}.mode-row{display:flex;gap:6px;margin-top:18px}.mode-row button{font-size:12px;flex:1;padding:8px}.navigation-app button.active{background:#e8f0fe;color:#1967d2;border-color:#aecbfa}.navigation-app .primary{width:100%;background:#1a73e8;border:0;color:white;border-radius:9px;padding:13px;margin:14px 0 2px;font-weight:600}.suggestions,.place-suggestions{list-style:none;padding:5px 0;margin:5px 0;background:white;max-height:230px;overflow:auto}.suggestions button,.place-suggestions button{width:100%;text-align:left;border:0;border-radius:0;padding:13px}.suggestions button:hover,.place-suggestions button:hover{background:#f1f5f9}.place-suggestions{position:absolute;left:20px;top:80px;width:390px;z-index:950;border-radius:12px;box-shadow:0 3px 12px #0002}.route-result{border-top:1px solid #eee;margin-top:20px;padding-top:16px}.route-result strong{display:block;font-size:28px;color:#188038}.route-result span{display:block}.route-result p,.muted{color:#64748b;font-size:12px;line-height:1.8}.parking-results h2{font-size:16px;margin:20px 0 3px}.parking-results .parking-card{width:100%;border:1px solid #e2e8f0;border-radius:10px;text-align:left;margin:7px 0;display:block;padding:14px}.parking-card b,.parking-card span,.parking-card small{display:block}.parking-card span{margin:6px 0;font-size:12px}.parking-card em{float:right;font-style:normal;font-size:17px;font-weight:700}.parking-card small{font-size:11px;color:#64748b}.tip{background:#e8f0fe;color:#1967d2;padding:8px;border-radius:6px}textarea{box-sizing:border-box;width:100%;min-height:80px;border:1px solid #dadce0;padding:10px;border-radius:8px;margin-top:14px}.error{background:#fef2f2;color:#b91c1c;padding:12px;border-radius:8px}.floating-error{position:absolute;top:90px;left:20px;z-index:750}.layer-switches{position:absolute;right:20px;top:80px;z-index:700;background:white;padding:10px 14px;border-radius:14px;box-shadow:0 2px 8px #0002;display:flex;gap:14px;font-size:12px}.layer-switches label{display:flex;gap:5px;align-items:center;cursor:pointer}.campus-fit{position:absolute;bottom:95px;right:12px;z-index:700}.road-legend{position:absolute;bottom:25px;left:50%;background:white;z-index:700;border-radius:18px;padding:8px 14px;display:flex;gap:12px;box-shadow:0 2px 8px #0002;font-size:11px}.road-legend i{display:inline-block;width:18px;height:4px;margin-right:5px;vertical-align:middle}:global(.campus-road-name){background:#fff9dd;border:0;box-shadow:none;font-size:11px;font-weight:600;color:#5d4e14;padding:2px 5px}@media(max-width:720px){.brand{top:10px;right:10px;padding:5px 10px}.brand span,.brand a{display:none}.search-shell{top:55px;left:10px;right:10px;width:auto}.place-suggestions{left:10px;right:10px;width:auto;top:110px}.navigation-panel,.navigation-panel.compact{left:10px;right:10px;bottom:15px;top:auto;width:auto;max-height:55vh;padding:18px}.layer-switches{left:10px;right:auto;top:115px;gap:10px;font-size:11px}.road-legend{top:163px;left:10px;bottom:auto;padding:6px 10px;gap:8px}.campus-fit{bottom:calc(55vh + 40px)}}
</style>
